hs_into_dict(path_prv) # get settings dicts in project.json # NB: may contain dunders self._dict_pub = F.load_paths_into_dict(path_pub) # if there was a problem except OSError as e: # from load_dicts # exit gracefully print(B.C.S_ERR_ERR, e) self._teardown(-1) # ---------------------------------------------------------------------- # fix dicts self._fix_dicts() # # ---------------------------------------------------------------------- # # print some info # print() # print(B.C.S_MSG_BAKE.format(self._dir_prj.name)) # print() # -------------------------------------------------------------------------- # Do any work before making dist # -------------------------------------------------------------------------- def _do_before_dist(self): """ Do any work before making dist Do any work on the dist folder before it is created. This method is called after _do_after_fix, and before _do_dist. """ B.C.do_before_dist( self._dir_prj, self._dict_prv, self._dict_pub, self._dict_act ) # -------------------------------------------------------------------------- # Copy fixed files to final location # -------------------------------------------------------------------------- # NB: HOWS THIS FOR A FUCKING IMPORT CHAIN?!?! @B.C.S.spin(B.C.S_ACTION_DIST) def _do_dist(self): """ Copy fixed files to final location Gets dirs/files from project and copies them to the dist/assets dir. """ # ---------------------------------------------------------------------- # do common dist stuff # find old dist? nuke it from orbit! it's the only way to be sure! a_dist = self._dir_prj / B.C.S_DIR_DIST if a_dist.is_dir(): shutil.rmtree(a_dist) # make child dir in case we nuked name_fmt = self._dict_prv_prj["__PP_FMT_DIST__"] p_dist = a_dist / name_fmt p_dist.mkdir(parents=True) # for each key, val (type, dict) for key, val in self._dict_pub_dist.items(): # get src/dst rel to prj dir/dist dir src = self._dir_prj / key dst = p_dist / str(val) if not dst.exists(): dst.mkdir(parents=True) dst = dst / src.name #